package syncmanager

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
	_ "time/tzdata"

	"github.com/google/uuid"
	backup "github.com/rcy1314/echo-noise/internal/backup"
	"github.com/rcy1314/echo-noise/internal/database"
	"github.com/rcy1314/echo-noise/internal/models"
	"gorm.io/gorm"
	"gorm.io/gorm/clause"
)

var DefaultManager = NewManager()

// Manager persists plans and history in the application's existing database.
// All file names are generated by the manager; public methods accept no paths.
type Manager struct {
	storeMu           sync.Mutex
	cloudMu           sync.Mutex
	warningMu         sync.Mutex
	discoveryWarnings map[string]string
	migrated          *gorm.DB
	lifecycleMu       sync.Mutex
	stop              context.CancelFunc
	done              chan struct{}
	activeMu          sync.Mutex
	active            map[string]context.CancelFunc
	db                func() *gorm.DB
	layout            func() backup.Layout
	root              string
	now               func() time.Time
	archive           func(context.Context, string, *gorm.DB, backup.Layout, backup.ArchiveKind, string) error
	cloud             managedCloud
}

func NewManager() *Manager {
	return &Manager{
		db:      func() *gorm.DB { return database.DB },
		layout:  backup.DefaultLayout,
		root:    filepath.Join("data", "backups"),
		now:     time.Now,
		archive: backup.CreateTypedArchive,
		cloud:   productionManagedCloud{},
		active:  make(map[string]context.CancelFunc),
	}
}

func (m *Manager) store() (*gorm.DB, error) {
	m.storeMu.Lock()
	defer m.storeMu.Unlock()
	db := m.db()
	if db == nil {
		return nil, errors.New("数据库未初始化")
	}
	if m.migrated != db {
		if err := db.AutoMigrate(&models.ManagedBackupPlan{}, &models.ManagedBackupRecord{}); err != nil {
			return nil, err
		}
		m.migrated = db
	}
	return db, nil
}

func validKind(kind string) bool {
	return kind == "data" || kind == "attachments" || kind == "server-config"
}

func normalizedScope(kind, scope string) (string, error) {
	if !validKind(kind) {
		return "", errors.New("无效的备份类型")
	}
	if kind == "attachments" {
		if scope == "" {
			scope = "all"
		}
		if scope != "all" && scope != "local" {
			return "", errors.New("附件范围必须为 all 或 local")
		}
	} else {
		if scope == "" {
			scope = "default"
		}
		if scope != "default" {
			return "", errors.New("此备份类型的范围必须为 default")
		}
	}
	return scope, nil
}

func validatePlan(plan models.ManagedBackupPlan) (models.ManagedBackupPlan, error) {
	var err error
	plan.Scope, err = normalizedScope(plan.Kind, plan.Scope)
	if err != nil {
		return plan, err
	}
	if plan.Target != "local" && plan.Target != "cloud" && plan.Target != "both" {
		return plan, errors.New("备份目标必须为 local、cloud 或 both")
	}
	if plan.KeepLocal < 1 || plan.KeepLocal > 1000 || plan.KeepCloud < 1 || plan.KeepCloud > 1000 {
		return plan, errors.New("保留数量必须为 1 到 1000")
	}
	if len(plan.Time) != 5 {
		return plan, errors.New("备份时间必须为 HH:MM")
	}
	if _, err := time.Parse("15:04", plan.Time); err != nil {
		return plan, errors.New("备份时间必须为 HH:MM")
	}
	if strings.TrimSpace(plan.Timezone) == "" || plan.Timezone == "Local" {
		return plan, errors.New("请指定 IANA 时区")
	}
	if _, err := time.LoadLocation(plan.Timezone); err != nil {
		return plan, fmt.Errorf("无效时区: %w", err)
	}
	plan.NextRun = nil
	return plan, nil
}

func (m *Manager) Plans() ([]models.ManagedBackupPlan, error) {
	db, err := m.store()
	if err != nil {
		return nil, err
	}
	for _, kind := range []string{"data", "attachments", "server-config"} {
		scope, _ := normalizedScope(kind, "")
		plan := models.ManagedBackupPlan{Kind: kind, Time: "03:00", Timezone: "UTC", Target: "local", Scope: scope, KeepLocal: 7, KeepCloud: 7}
		if err := db.Clauses(clause.OnConflict{DoNothing: true}).Create(&plan).Error; err != nil {
			return nil, err
		}
	}
	var plans []models.ManagedBackupPlan
	if err := db.Order("kind ASC").Find(&plans).Error; err != nil {
		return nil, err
	}
	for i := range plans {
		plans[i].NextRun = nextRun(plans[i], m.now())
	}
	return plans, nil
}

// SavePlan preserves the durable claim even when a client supplies LastRun.
// Retention counts are bounded positive values, matching the controller UI.
func (m *Manager) SavePlan(plan models.ManagedBackupPlan) (models.ManagedBackupPlan, error) {
	plan, err := validatePlan(plan)
	if err != nil {
		return plan, err
	}
	db, err := m.store()
	if err != nil {
		return plan, err
	}
	plan.LastRun, plan.NextRun = nil, nil
	plan.Revision = 1
	assignments := map[string]interface{}{
		"enabled": plan.Enabled, "time": plan.Time, "timezone": plan.Timezone,
		"keep_local": plan.KeepLocal, "keep_cloud": plan.KeepCloud,
		"target": plan.Target, "scope": plan.Scope,
		"revision": gorm.Expr("revision + 1"), "updated_at": m.now(),
	}
	if err := db.Clauses(clause.OnConflict{Columns: []clause.Column{{Name: "kind"}}, DoUpdates: clause.Assignments(assignments)}).Create(&plan).Error; err != nil {
		return plan, err
	}
	if err := db.First(&plan, "kind = ?", plan.Kind).Error; err != nil {
		return plan, err
	}
	plan.NextRun = nextRun(plan, m.now())
	return plan, nil
}

// dailySlot deliberately skips a nonexistent clock time during a DST gap. A
// repeated clock time can only be claimed once because LastRun is durable.
func dailySlot(plan models.ManagedBackupPlan, now time.Time) (time.Time, bool) {
	loc, err := time.LoadLocation(plan.Timezone)
	if err != nil {
		return time.Time{}, false
	}
	clock, err := time.Parse("15:04", plan.Time)
	if err != nil {
		return time.Time{}, false
	}
	local := now.In(loc)
	slot := time.Date(local.Year(), local.Month(), local.Day(), clock.Hour(), clock.Minute(), 0, 0, loc)
	if slot.Hour() != clock.Hour() || slot.Minute() != clock.Minute() {
		return time.Time{}, false
	}
	return slot.UTC(), true
}

func claimedToday(plan models.ManagedBackupPlan, slot time.Time) bool {
	if plan.LastRun == nil {
		return false
	}
	loc, err := time.LoadLocation(plan.Timezone)
	if err != nil {
		return true
	}
	return !plan.LastRun.Before(slot) || plan.LastRun.In(loc).Format("2006-01-02") == slot.In(loc).Format("2006-01-02")
}

func nextRun(plan models.ManagedBackupPlan, now time.Time) *time.Time {
	if !plan.Enabled {
		return nil
	}
	loc, err := time.LoadLocation(plan.Timezone)
	if err != nil {
		return nil
	}
	for day := range 4 {
		date := now.In(loc).AddDate(0, 0, day)
		slot, ok := dailySlot(plan, date)
		if ok && slot.After(now) && !claimedToday(plan, slot) {
			return &slot
		}
	}
	return nil
}

// Start is idempotent and independent of legacy cloud synchronization settings.
// Scanning only creates backups; it never opens or stages a restore package.
func (m *Manager) Start(ctx context.Context) {
	m.lifecycleMu.Lock()
	defer m.lifecycleMu.Unlock()
	if m.stop != nil {
		return
	}
	ctx, m.stop = context.WithCancel(ctx)
	m.done = make(chan struct{})
	go func(done chan struct{}) {
		defer close(done)
		// A restored data snapshot contains its own unfinished history row.
		// Reconcile once at startup as well as on explicit history refreshes.
		discoveryCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
		if err := m.Discover(discoveryCtx, ""); err != nil && ctx.Err() == nil {
			log.Printf("托管备份中断任务核对失败: %v", err)
		}
		cancel()
		ticker := time.NewTicker(30 * time.Second)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				if err := m.Scan(ctx); err != nil && !errors.Is(err, context.Canceled) {
					log.Printf("托管备份计划扫描失败: %v", err)
				}
			}
		}
	}(m.done)
}

// Stop cancels scheduled work, including work waiting for the operation lock.
func (m *Manager) Stop() {
	m.lifecycleMu.Lock()
	defer m.lifecycleMu.Unlock()
	if m.stop != nil {
		m.stop()
		<-m.done
		m.stop, m.done = nil, nil
	}
}

// LockOperationContext interoperates with LockOperation while allowing a queued
// request or scheduled job to be canceled before it acquires the lock.
func LockOperationContext(ctx context.Context) (func(), error) {
	return lockContext(ctx, &operationMu)
}

func lockContext(ctx context.Context, mutex *sync.Mutex) (func(), error) {
	ticker := time.NewTicker(20 * time.Millisecond)
	defer ticker.Stop()
	for {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		if mutex.TryLock() {
			return mutex.Unlock, nil
		}
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-ticker.C:
		}
	}
}

// Scan claims today's due slots atomically before creating a history entry.
// A failed or interrupted job consumes its slot, so restart cannot loop retries.
func (m *Manager) Scan(ctx context.Context) error {
	plans, err := m.Plans()
	if err != nil {
		return err
	}
	var failures []error
	for _, plan := range plans {
		if !plan.Enabled {
			continue
		}
		slot, ok := dailySlot(plan, m.now())
		if !ok || slot.After(m.now()) || claimedToday(plan, slot) {
			continue
		}
		release, err := LockOperationContext(ctx)
		if err != nil {
			return err
		}
		err = m.runScheduled(ctx, plan, slot)
		release()
		if err != nil {
			failures = append(failures, err)
		}
	}
	return errors.Join(failures...)
}

func (m *Manager) runScheduled(ctx context.Context, plan models.ManagedBackupPlan, slot time.Time) error {
	db, err := m.store()
	if err != nil {
		return err
	}
	record := newRecord(plan.Kind, plan.Target, plan.Scope, "scheduled", m.now())
	claimed := false
	err = db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		query := tx.Model(&models.ManagedBackupPlan{}).Where("kind = ? AND enabled = ? AND revision = ?", plan.Kind, true, plan.Revision)
		if plan.LastRun == nil {
			query = query.Where("last_run IS NULL")
		} else {
			query = query.Where("last_run = ?", *plan.LastRun)
		}
		result := query.Update("last_run", slot)
		if result.Error != nil {
			return result.Error
		}
		if result.RowsAffected == 0 {
			return nil
		}
		claimed = true
		return tx.Create(&record).Error
	})
	if err != nil || !claimed {
		return err
	}
	_, err = m.execute(ctx, db, record, &plan)
	return err
}

func newRecord(kind, target, scope, trigger string, now time.Time) models.ManagedBackupRecord {
	return models.ManagedBackupRecord{ID: uuid.NewString(), Kind: kind, Target: target, Scope: scope, Trigger: trigger, CreatedAt: now.UTC(), Status: "running"}
}

func (m *Manager) Create(ctx context.Context, kind, target, scope, trigger string) (models.ManagedBackupRecord, error) {
	var record models.ManagedBackupRecord
	scope, err := normalizedScope(kind, scope)
	if err != nil {
		return record, err
	}
	if target != "local" && target != "cloud" && target != "both" {
		return record, errors.New("无效的备份目标")
	}
	if trigger != "manual" && trigger != "scheduled" {
		return record, errors.New("无效的备份触发方式")
	}
	release, err := LockOperationContext(ctx)
	if err != nil {
		return record, err
	}
	defer release()
	db, err := m.store()
	if err != nil {
		return record, err
	}
	if _, err := m.Plans(); err != nil {
		return record, err
	}
	record = newRecord(kind, target, scope, trigger, m.now())
	if err := db.WithContext(ctx).Create(&record).Error; err != nil {
		return record, err
	}
	var plan models.ManagedBackupPlan
	err = db.First(&plan, "kind = ?", kind).Error
	if err != nil {
		return m.finish(db, record, err)
	}
	return m.execute(ctx, db, record, &plan)
}

// Cancel cancels a currently executing managed job; callers may also cancel the
// context passed to Create. Completed jobs cannot be canceled retroactively.
func (m *Manager) Cancel(id string) bool {
	m.activeMu.Lock()
	defer m.activeMu.Unlock()
	cancel, ok := m.active[id]
	if ok {
		cancel()
	}
	return ok
}

func (m *Manager) execute(ctx context.Context, db *gorm.DB, record models.ManagedBackupRecord, plan *models.ManagedBackupPlan) (models.ManagedBackupRecord, error) {
	ctx, cancel := context.WithCancel(ctx)
	m.activeMu.Lock()
	m.active[record.ID] = cancel
	m.activeMu.Unlock()
	defer func() { cancel(); m.activeMu.Lock(); delete(m.active, record.ID); m.activeMu.Unlock() }()
	if record.Kind == "data" {
		dbType := strings.TrimSpace(os.Getenv("DB_TYPE"))
		if (dbType != "" && dbType != "sqlite") || db.Dialector == nil || db.Dialector.Name() != "sqlite" {
			return m.finish(db, record, errors.New("独立数据备份目前仅支持 SQLite；不支持外部数据库备份"))
		}
	}
	path, err := m.recordPath(record)
	if err != nil {
		return m.finish(db, record, err)
	}
	if err := m.safeDirectory(record.Kind, true); err != nil {
		return m.finish(db, record, err)
	}
	stage := path + ".partial"
	defer os.Remove(stage)
	if err := ctx.Err(); err != nil {
		return m.finish(db, record, err)
	}
	if err := m.archive(ctx, stage, db, m.layout(), backup.ArchiveKind(record.Kind), record.Scope); err != nil {
		return m.finish(db, record, err)
	}
	if err := ctx.Err(); err != nil {
		return m.finish(db, record, err)
	}
	info, err := os.Lstat(stage)
	if err != nil {
		return m.finish(db, record, err)
	}
	if !info.Mode().IsRegular() || info.Size() == 0 {
		return m.finish(db, record, errors.New("备份归档必须为非空普通文件"))
	}
	if err := os.Chmod(stage, 0600); err != nil {
		return m.finish(db, record, err)
	}
	record.Size = info.Size()
	if record.Target == "local" || record.Target == "both" {
		if err := os.Rename(stage, path); err != nil {
			return m.finish(db, record, err)
		}
		record.Local = true
		stage = path
	}
	if record.Target == "cloud" || record.Target == "both" {
		releaseCloud, err := lockContext(ctx, &m.cloudMu)
		if err != nil {
			return m.finish(db, record, err)
		}
		defer releaseCloud()
		record.CloudKey = managedKey(record.Kind, record.ID)
		if err := m.cloud.Upload(ctx, record.CloudKey, stage); err != nil {
			return m.finish(db, record, err)
		}
		record.Cloud = true
	}
	// Persist availability before retention. Failed uploads never prune copies.
	record, err = m.finish(db, record, nil)
	if err != nil {
		return record, err
	}
	if plan != nil {
		if err := m.retain(ctx, db, *plan, record); err != nil {
			record.Error = "备份已创建，保留清理失败: " + err.Error()
			persistErr := db.Model(&record).Update("error", record.Error).Error
			return record, errors.Join(err, persistErr)
		}
	}
	return record, nil
}

func (m *Manager) finish(db *gorm.DB, record models.ManagedBackupRecord, cause error) (models.ManagedBackupRecord, error) {
	now := m.now().UTC()
	record.FinishedAt = &now
	record.Status = "success"
	if cause != nil {
		record.Status, record.Error = "failed", cause.Error()
		if errors.Is(cause, context.Canceled) || errors.Is(cause, context.DeadlineExceeded) {
			record.Status = "canceled"
		}
	}
	// The request context may be canceled; audit persistence must still complete.
	err := db.Save(&record).Error
	return record, errors.Join(cause, err)
}

func (m *Manager) recordPath(record models.ManagedBackupRecord) (string, error) {
	if !validKind(record.Kind) {
		return "", errors.New("无效的备份类型")
	}
	if !validRecordID(record.ID) {
		return "", errors.New("无效的备份记录 ID")
	}
	return filepath.Join(m.Directory(record.Kind), record.ID+".zip"), nil
}

// History refreshes local and cloud discovery before reading the durable audit log.
// HTTP callers may use HistoryContext to propagate request cancellation.
func (m *Manager) History(kind string) ([]models.ManagedBackupRecord, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	return m.HistoryContext(ctx, kind)
}

func (m *Manager) HistoryContext(ctx context.Context, kind string) ([]models.ManagedBackupRecord, error) {
	if kind != "" && !validKind(kind) {
		return nil, errors.New("无效的备份类型")
	}
	discoveryCtx, cancelDiscovery := context.WithTimeout(ctx, 15*time.Second)
	discoveryErr := m.Discover(discoveryCtx, kind)
	warningErr := discoveryErr
	cancelDiscovery()
	if ctx.Err() != nil {
		return nil, ctx.Err()
	}
	m.warningMu.Lock()
	if m.discoveryWarnings == nil {
		m.discoveryWarnings = make(map[string]string)
	}
	kinds := []string{kind}
	if kind == "" {
		kinds = []string{"data", "attachments", "server-config"}
	}
	for _, current := range kinds {
		delete(m.discoveryWarnings, current)
		if warningErr != nil {
			m.discoveryWarnings[current] = warningErr.Error()
		}
	}
	m.warningMu.Unlock()
	db, err := m.store()
	if err != nil {
		return nil, err
	}
	query := db.WithContext(ctx).Order("created_at DESC, id DESC")
	if kind != "" {
		query = query.Where("kind = ?", kind)
	}
	records := []models.ManagedBackupRecord{}
	err = query.Find(&records).Error
	if discoveryErr != nil || !m.cloud.Enabled() {
		for i := range records {
			records[i].Cloud = false
		}
	}
	return records, err
}

// DiscoveryWarnings reports the last history refresh failure for each kind.
// Controllers must filter by the same kind permissions as plans and records.
func (m *Manager) DiscoveryWarnings(kind string) []string {
	m.warningMu.Lock()
	defer m.warningMu.Unlock()
	result := []string{}
	for _, current := range []string{"data", "attachments", "server-config"} {
		if kind != "" && current != kind {
			continue
		}
		if warning := m.discoveryWarnings[current]; warning != "" {
			result = append(result, warning)
		}
	}
	return result
}

func (m *Manager) FetchRecord(ctx context.Context, id string) (models.ManagedBackupRecord, error) {
	var record models.ManagedBackupRecord
	if !validRecordID(id) {
		return record, errors.New("无效的备份记录 ID")
	}
	db, err := m.store()
	if err != nil {
		return record, err
	}
	err = db.WithContext(ctx).First(&record, "id = ?", id).Error
	return record, err
}

// Open chooses an available copy. Controllers must hold LockOperation through
// reading and restoring to interoperate with retention and update shutdown.
func (m *Manager) Open(ctx context.Context, id string) (io.ReadCloser, string, error) {
	return m.OpenSource(ctx, id, "")
}

// OpenSource respects an explicit source; it never falls back to another copy.
func (m *Manager) OpenSource(ctx context.Context, id, source string) (io.ReadCloser, string, error) {
	if source != "" && source != "local" && source != "cloud" {
		return nil, "", errors.New("无效的备份来源")
	}
	record, err := m.FetchRecord(ctx, id)
	if err != nil {
		return nil, "", err
	}
	path, err := m.recordPath(record)
	if err != nil {
		return nil, "", err
	}
	var reader io.ReadCloser
	if record.Local && source != "cloud" {
		if err := m.safeDirectory(record.Kind, false); err != nil && !(source == "" && errors.Is(err, os.ErrNotExist)) {
			return nil, "", err
		}
		info, statErr := os.Lstat(path)
		if statErr == nil && !info.Mode().IsRegular() {
			return nil, "", errors.New("备份文件不是普通文件")
		}
		if statErr == nil {
			reader, err = os.Open(path)
		} else {
			err = statErr
		}
		if err != nil && !errors.Is(err, os.ErrNotExist) {
			return nil, "", err
		}
	}
	if reader == nil && record.Cloud && source != "local" {
		if record.CloudKey != managedKey(record.Kind, record.ID) {
			return nil, "", errors.New("无效的云备份键")
		}
		reader, err = m.cloud.Open(ctx, record.CloudKey)
	}
	if reader == nil {
		if err == nil {
			err = os.ErrNotExist
		}
		return nil, "", err
	}
	return reader, record.Kind + "-" + record.ID + ".zip", nil
}

// Directory returns the absolute directory used by recordPath, including before
// the first backup creates it. Invalid kinds never expose the storage root.
func (m *Manager) Directory(kind string) string {
	if !validKind(kind) {
		return ""
	}
	folder := map[string]string{"data": "database", "attachments": "attachments", "server-config": "config"}[kind]
	directory, err := filepath.Abs(filepath.Join(m.root, folder))
	if err != nil {
		return ""
	}
	return directory
}

// Reject links in every existing directory component, including parents of
// data/backups, so managed storage cannot be redirected to an arbitrary tree.
func (m *Manager) safeDirectory(kind string, create bool) error {
	directory, err := filepath.Abs(m.Directory(kind))
	if err != nil {
		return err
	}
	var paths []string
	for current := directory; ; current = filepath.Dir(current) {
		paths = append(paths, current)
		if filepath.Dir(current) == current {
			break
		}
	}
	for i := len(paths) - 1; i >= 0; i-- {
		info, err := os.Lstat(paths[i])
		if errors.Is(err, os.ErrNotExist) && create {
			if err := os.Mkdir(paths[i], 0700); err != nil && !errors.Is(err, os.ErrExist) {
				return err
			}
			info, err = os.Lstat(paths[i])
		}
		if err != nil {
			return err
		}
		if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
			return errors.New("备份目录必须为本地普通目录")
		}
	}
	return nil
}
